import { useEffect, useRef } from 'react';
import * as THREE from 'three';
import { LineSegments2 }     from 'three/examples/jsm/lines/LineSegments2.js';
import { LineSegmentsGeometry } from 'three/examples/jsm/lines/LineSegmentsGeometry.js';
import { LineMaterial }      from 'three/examples/jsm/lines/LineMaterial.js';

// ── Topology ──
const AS_COUNT   = 5;
const MIN_SEP    = 275;
const NPC        = 10;
const C          = AS_COUNT * NPC;
const CLUSTER_R  = 100;
const INTRA_DIST = 140;
const INTER_DIST = 400;
const MAX_GW     = 3;
const SPRING_K   = 0.038;
const DAMPING    = 0.84;
const MOUSE_RAD  = 220;
const REPEL      = 3200;
const MAX_INTRA  = 512;   // actual max = AS_COUNT * NPC*(NPC-1)/2 ≈ 225
const MAX_INTER  = 128;   // actual max ≈ AS_COUNT*(AS_COUNT-1)/2 * MAX_GW ≈ 30

// ── Packets ──
const MAX_SIG    = 20;
const SIG_SPEED  = 0.024;
const ARRIVE_MS  = 380;
const DEAD_MS    = 900;
const BREAK_DISP = 25;
const X_SIZE     = 11;
const X_BLINK_MS = 360;
const X_LIFE_MS  = 2200;

function randomCenters(halfW: number, halfH: number): [number, number, number][] {
  const portrait = halfW < halfH;
  const xMin = portrait ? -halfW * 0.8 : halfW * 0.1;
  const xMax = portrait ?  halfW * 0.8 : halfW * 0.85;
  const yTop =  halfH * 0.75;
  const yBot = -halfH * 0.88;
  const sep  = Math.min(MIN_SEP, ((xMax - xMin) * 0.9) / Math.ceil(Math.sqrt(AS_COUNT)));
  const centers: [number, number, number][] = [];
  let attempts = 0;
  while (centers.length < AS_COUNT && attempts < 2000) {
    attempts++;
    const x = xMin + Math.random() * (xMax - xMin);
    const y = yBot  + Math.random() * (yTop - yBot);
    const z = (Math.random() - 0.5) * 50;
    const ok = centers.every(([ex, ey]) => Math.sqrt((x-ex)**2 + (y-ey)**2) >= sep);
    if (ok) centers.push([x, y, z]);
  }
  while (centers.length < AS_COUNT)
    centers.push([xMin + Math.random()*(xMax-xMin), yBot + Math.random()*(yTop-yBot), 0]);
  return centers;
}

export function useBGPTopology(
  containerRef: React.RefObject<HTMLDivElement | null>,
  accentColor: string,
) {
  const lineMatRef = useRef<LineMaterial              | null>(null);
  const gwMatRef   = useRef<THREE.PointsMaterial      | null>(null);
  const sigMatRef  = useRef<THREE.PointsMaterial      | null>(null);
  const xMatRef    = useRef<THREE.LineBasicMaterial   | null>(null);
  const hlMatRef   = useRef<LineMaterial              | null>(null);

  useEffect(() => {
    if (lineMatRef.current) lineMatRef.current.color.setStyle(accentColor);
    if (gwMatRef.current)   gwMatRef.current.color.setStyle(accentColor);
    if (xMatRef.current)    xMatRef.current.color.setStyle(accentColor);
    if (hlMatRef.current)   hlMatRef.current.color.setStyle(accentColor);
  }, [accentColor]);

  // eslint-disable-next-line react-hooks/exhaustive-deps
  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    const scene  = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 2000);
    camera.position.z = 500;

    const renderer = new THREE.WebGLRenderer({ alpha: true, antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.setClearColor(0x000000, 0);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    container.appendChild(renderer.domElement);

    // ── Node positions ──
    const origPos = new Float32Array(C * 3);
    const currPos = new Float32Array(C * 3);
    const vel     = new Float32Array(C * 3);
    const nodeAS  = new Uint8Array(C);

    const halfH   = Math.tan((75 / 2) * Math.PI / 180) * 500;
    const halfW   = halfH * (window.innerWidth / window.innerHeight);
    const centers = randomCenters(halfW, halfH);
    for (let ci = 0; ci < centers.length; ci++) {
      const [cx, cy, cz] = centers[ci];
      for (let ni = 0; ni < NPC; ni++) {
        const i     = ci * NPC + ni;
        nodeAS[i]   = ci;
        const r     = CLUSTER_R * Math.cbrt(Math.random());
        const theta = Math.random() * Math.PI * 2;
        const phi   = Math.acos(2 * Math.random() - 1);
        origPos[i*3]   = currPos[i*3]   = cx + r * Math.sin(phi) * Math.cos(theta);
        origPos[i*3+1] = currPos[i*3+1] = cy + r * Math.sin(phi) * Math.sin(theta);
        origPos[i*3+2] = currPos[i*3+2] = cz + r * Math.cos(phi) * 0.22;
      }
    }

    // ── Build static adjacency list from initial positions ──
    const adj: number[][] = Array.from({ length: C }, () => []);

    // Intra-cluster edges
    for (let i = 0; i < C; i++) {
      for (let j = i + 1; j < C; j++) {
        if (nodeAS[i] !== nodeAS[j]) continue;
        const dx = origPos[i*3]-origPos[j*3];
        const dy = origPos[i*3+1]-origPos[j*3+1];
        const dz = origPos[i*3+2]-origPos[j*3+2];
        if (Math.sqrt(dx*dx+dy*dy+dz*dz) < INTRA_DIST) {
          adj[i].push(j); adj[j].push(i);
        }
      }
    }

    // Inter-cluster BGP edges — MAX_GW nearest pairs per AS-pair
    for (let ca = 0; ca < AS_COUNT; ca++) {
      for (let cb = ca + 1; cb < AS_COUNT; cb++) {
        const pairs: { i: number; j: number; d: number }[] = [];
        for (let na = 0; na < NPC; na++) {
          for (let nb = 0; nb < NPC; nb++) {
            const i = ca*NPC+na, j = cb*NPC+nb;
            const dx = origPos[i*3]-origPos[j*3];
            const dy = origPos[i*3+1]-origPos[j*3+1];
            const dz = origPos[i*3+2]-origPos[j*3+2];
            const d  = Math.sqrt(dx*dx+dy*dy+dz*dz);
            if (d < INTER_DIST) pairs.push({ i, j, d });
          }
        }
        pairs.sort((a, b) => a.d - b.d);
        for (let k = 0; k < Math.min(MAX_GW, pairs.length); k++) {
          const { i, j } = pairs[k];
          adj[i].push(j); adj[j].push(i);
        }
      }
    }

    // ── BFS shortest path ──
    function bfs(src: number, dst: number): number[] | null {
      if (src === dst) return [src];
      const prev = new Int16Array(C).fill(-1);
      const visited = new Uint8Array(C);
      const queue: number[] = [src];
      visited[src] = 1;
      while (queue.length > 0) {
        const node = queue.shift()!;
        for (const nb of adj[node]) {
          if (visited[nb]) continue;
          visited[nb] = 1;
          prev[nb] = node;
          if (nb === dst) {
            const path: number[] = [];
            let cur: number = dst;
            while (cur !== -1) { path.push(cur); cur = prev[cur]; }
            return path.reverse();
          }
          queue.push(nb);
        }
      }
      return null;
    }

    // ── Three.js objects ──
    const nodeGeom    = new THREE.BufferGeometry();
    const nodePosAttr = new THREE.BufferAttribute(currPos, 3);
    nodePosAttr.setUsage(THREE.DynamicDrawUsage);
    nodeGeom.setAttribute('position', nodePosAttr);
    scene.add(new THREE.Points(nodeGeom,
      new THREE.PointsMaterial({ color: 0xffffff, size: 2.5, transparent: true, opacity: 1.0 })));

    const isGateway  = new Uint8Array(C);
    const gwPosBuf   = new Float32Array(AS_COUNT * AS_COUNT * MAX_GW * 2 * 3);
    const gwGeom     = new THREE.BufferGeometry();
    const gwPosAttr  = new THREE.BufferAttribute(gwPosBuf, 3);
    gwPosAttr.setUsage(THREE.DynamicDrawUsage);
    gwGeom.setAttribute('position', gwPosAttr);
    const gwMat = new THREE.PointsMaterial({ color: accentColor, size: 6.5, transparent: true, opacity: 1.0 });
    gwMatRef.current = gwMat;
    scene.add(new THREE.Points(gwGeom, gwMat));

    const intraPosArr  = new Float32Array(MAX_INTRA * 6);
    const intraGeom    = new LineSegmentsGeometry();
    intraGeom.setPositions(new Float32Array(MAX_INTRA * 6));
    const intraInstBuf = (intraGeom.getAttribute('instanceStart') as THREE.InterleavedBufferAttribute).data as THREE.InstancedInterleavedBuffer;
    const intraBufArr  = intraInstBuf.array as Float32Array;
    const intraMat = new LineMaterial({ color: 0xffffff, linewidth: 1.2, transparent: true, opacity: 0.5, resolution: new THREE.Vector2(window.innerWidth, window.innerHeight) });
    scene.add(new LineSegments2(intraGeom, intraMat));

    const interPosArr  = new Float32Array(MAX_INTER * 6);
    const interGeom    = new LineSegmentsGeometry();
    interGeom.setPositions(new Float32Array(MAX_INTER * 6));
    const interInstBuf = (interGeom.getAttribute('instanceStart') as THREE.InterleavedBufferAttribute).data as THREE.InstancedInterleavedBuffer;
    const interBufArr  = interInstBuf.array as Float32Array;
    const interMat     = new LineMaterial({ color: new THREE.Color(accentColor).getHex(), linewidth: 2.0, transparent: true, opacity: 0.85, resolution: new THREE.Vector2(window.innerWidth, window.innerHeight) });
    lineMatRef.current = interMat;
    scene.add(new LineSegments2(interGeom, interMat));

    const candD     = new Float32Array(NPC * NPC);
    const candI     = new Uint16Array(NPC * NPC);
    const candJ     = new Uint16Array(NPC * NPC);
    const gwPairMap = new Uint8Array(C * C);

    const hlPosBuf  = new Float32Array(MAX_SIG * 6);
    const hlGeom    = new LineSegmentsGeometry();
    hlGeom.setPositions(new Float32Array(MAX_SIG * 6));
    const hlInstBuf = (hlGeom.getAttribute('instanceStart') as THREE.InterleavedBufferAttribute).data as THREE.InstancedInterleavedBuffer;
    const hlBufArr  = hlInstBuf.array as Float32Array;
    const hlMat     = new LineMaterial({ color: new THREE.Color(accentColor).getHex(), linewidth: 2.5, transparent: true, opacity: 0.6, resolution: new THREE.Vector2(window.innerWidth, window.innerHeight) });
    hlMatRef.current = hlMat;
    scene.add(new LineSegments2(hlGeom, hlMat));

    const sigPosBuf = new Float32Array(MAX_SIG * 3);
    const sigGeom   = new THREE.BufferGeometry();
    const sigPA     = new THREE.BufferAttribute(sigPosBuf, 3);
    sigPA.setUsage(THREE.DynamicDrawUsage);
    sigGeom.setAttribute('position', sigPA);
    const sigMat = new THREE.PointsMaterial({ color: 0xffffff, size: 8.0, transparent: true, opacity: 1.0 });
    sigMatRef.current = sigMat;
    scene.add(new THREE.Points(sigGeom, sigMat));

    const xPosBuf = new Float32Array(MAX_SIG * 4 * 3);
    const xGeom   = new THREE.BufferGeometry();
    const xPA     = new THREE.BufferAttribute(xPosBuf, 3);
    xPA.setUsage(THREE.DynamicDrawUsage);
    xGeom.setAttribute('position', xPA);
    const xMat = new THREE.LineBasicMaterial({ color: accentColor, transparent: true, opacity: 0.0 });
    xMatRef.current = xMat;
    scene.add(new THREE.LineSegments(xGeom, xMat));

    // ── Packet state ──
    type SigState = 'traveling' | 'arrived' | 'dead';
    type Sig = {
      path: number[];
      pathIdx: number;
      progress: number;
      state: SigState;
      stateAt: number;
      broken: boolean;
      bx: number; by: number; bz: number;
      brokenAt: number;
    };
    const sigs: Sig[] = Array.from({ length: MAX_SIG }, (_, i) => ({
      path: [], pathIdx: 0, progress: 0,
      state: 'dead' as SigState,
      stateAt: Date.now() - i * (DEAD_MS / MAX_SIG),
      broken: false, bx: 0, by: 0, bz: 0, brokenAt: 0,
    }));

    function nodeDisplaced(i: number): boolean {
      const dx = currPos[i*3]   - origPos[i*3];
      const dy = currPos[i*3+1] - origPos[i*3+1];
      const dz = currPos[i*3+2] - origPos[i*3+2];
      return dx*dx + dy*dy + dz*dz > BREAK_DISP * BREAK_DISP;
    }

    function spawnSig(sig: Sig) {
      // Prefer cross-AS routing: src and dst in different AS
      for (let attempt = 0; attempt < 20; attempt++) {
        const srcAS = Math.floor(Math.random() * AS_COUNT);
        const dstAS = (srcAS + 1 + Math.floor(Math.random() * (AS_COUNT - 1))) % AS_COUNT;
        const src   = srcAS * NPC + Math.floor(Math.random() * NPC);
        const dst   = dstAS * NPC + Math.floor(Math.random() * NPC);
        const path  = bfs(src, dst);
        if (path && path.length >= 2) {
          sig.path     = path;
          sig.pathIdx  = 0;
          sig.progress = 0;
          sig.state    = 'traveling';
          sig.stateAt  = Date.now();
          sig.broken   = false;
          return;
        }
      }
      // Fallback: intra-cluster if no cross-AS path found
      for (let attempt = 0; attempt < 10; attempt++) {
        const as   = Math.floor(Math.random() * AS_COUNT);
        const src  = as * NPC + Math.floor(Math.random() * NPC);
        const dst  = as * NPC + Math.floor(Math.random() * NPC);
        if (src === dst) continue;
        const path = bfs(src, dst);
        if (path && path.length >= 2) {
          sig.path     = path;
          sig.pathIdx  = 0;
          sig.progress = 0;
          sig.state    = 'traveling';
          sig.stateAt  = Date.now();
          sig.broken   = false;
          return;
        }
      }
      sig.state = 'dead'; sig.stateAt = Date.now();
    }

    const mouse      = { x: 99999, y: 99999 };
    const mouseNDC   = new THREE.Vector2();
    const raycaster  = new THREE.Raycaster();
    const mousePlane = new THREE.Plane(new THREE.Vector3(0, 0, 1), 0);
    const mouseWorld = new THREE.Vector3();
    const onMouseMove = (e: MouseEvent) => { mouse.x = e.clientX; mouse.y = e.clientY; };
    window.addEventListener('mousemove', onMouseMove);

    let animId: number;

    function animate() {
      animId = requestAnimationFrame(animate);

      mouseNDC.set((mouse.x/window.innerWidth)*2-1, (mouse.y/window.innerHeight)*-2+1);
      raycaster.setFromCamera(mouseNDC, camera);
      raycaster.ray.intersectPlane(mousePlane, mouseWorld);

      // Physics
      for (let i = 0; i < C; i++) {
        const ix=i*3, iy=ix+1, iz=ix+2;
        vel[ix] += (origPos[ix]-currPos[ix])*SPRING_K;
        vel[iy] += (origPos[iy]-currPos[iy])*SPRING_K;
        vel[iz] += (origPos[iz]-currPos[iz])*SPRING_K;
        const dx=currPos[ix]-mouseWorld.x, dy=currPos[iy]-mouseWorld.y;
        const d=Math.sqrt(dx*dx+dy*dy);
        if (d < MOUSE_RAD && d > 1) { const f=REPEL/(d*d); vel[ix]+=(dx/d)*f; vel[iy]+=(dy/d)*f; }
        vel[ix]*=DAMPING; vel[iy]*=DAMPING; vel[iz]*=DAMPING;
        currPos[ix]+=vel[ix]; currPos[iy]+=vel[iy]; currPos[iz]+=vel[iz];
      }
      nodePosAttr.needsUpdate = true;

      // Intra lines (visual only — topology is static)
      let ii = 0;
      for (let i = 0; i < C; i++) {
        for (let j = i+1; j < C; j++) {
          if (nodeAS[i] !== nodeAS[j]) continue;
          const dx=currPos[i*3]-currPos[j*3], dy=currPos[i*3+1]-currPos[j*3+1], dz=currPos[i*3+2]-currPos[j*3+2];
          if (Math.sqrt(dx*dx+dy*dy+dz*dz) < INTRA_DIST && ii+6 <= intraPosArr.length) {
            intraPosArr[ii++]=currPos[i*3];   intraPosArr[ii++]=currPos[i*3+1]; intraPosArr[ii++]=currPos[i*3+2];
            intraPosArr[ii++]=currPos[j*3];   intraPosArr[ii++]=currPos[j*3+1]; intraPosArr[ii++]=currPos[j*3+2];
          }
        }
      }
      intraBufArr.set(intraPosArr.subarray(0, ii));
      if (ii < MAX_INTRA * 6) intraBufArr.fill(0, ii);
      intraInstBuf.needsUpdate = true;

      // BGP lines (visual only)
      let xi=0;
      isGateway.fill(0); gwPairMap.fill(0);
      for (let ca=0; ca<AS_COUNT; ca++) {
        for (let cb=ca+1; cb<AS_COUNT; cb++) {
          let nc=0;
          for (let na=0; na<NPC; na++) for (let nb=0; nb<NPC; nb++) {
            const i=ca*NPC+na, j=cb*NPC+nb;
            const dx=currPos[i*3]-currPos[j*3], dy=currPos[i*3+1]-currPos[j*3+1], dz=currPos[i*3+2]-currPos[j*3+2];
            const d=Math.sqrt(dx*dx+dy*dy+dz*dz);
            if (d<INTER_DIST) { candD[nc]=d; candI[nc]=i; candJ[nc]=j; nc++; }
          }
          const keep=Math.min(MAX_GW,nc);
          for (let k=0; k<keep; k++) {
            let minK=k;
            for (let m=k+1; m<nc; m++) if (candD[m]<candD[minK]) minK=m;
            let td=candD[k]; candD[k]=candD[minK]; candD[minK]=td;
            let ti=candI[k]; candI[k]=candI[minK]; candI[minK]=ti;
            let tj=candJ[k]; candJ[k]=candJ[minK]; candJ[minK]=tj;
            const i=candI[k], j=candJ[k];
            if (xi+6<=interPosArr.length) {
              interPosArr[xi++]=currPos[i*3]; interPosArr[xi++]=currPos[i*3+1]; interPosArr[xi++]=currPos[i*3+2];
              interPosArr[xi++]=currPos[j*3]; interPosArr[xi++]=currPos[j*3+1]; interPosArr[xi++]=currPos[j*3+2];
              isGateway[i]=1; isGateway[j]=1; gwPairMap[i*C+j]=1; gwPairMap[j*C+i]=1;
            }
          }
        }
      }
      interBufArr.set(interPosArr.subarray(0, xi));
      if (xi < MAX_INTER * 6) interBufArr.fill(0, xi);
      interInstBuf.needsUpdate = true;

      let gi=0;
      for (let i=0; i<C; i++) { if (!isGateway[i]) continue; gwPosBuf[gi++]=currPos[i*3]; gwPosBuf[gi++]=currPos[i*3+1]; gwPosBuf[gi++]=currPos[i*3+2]; }
      gwGeom.setDrawRange(0, gi/3); gwPosAttr.needsUpdate=true;

      // ── Packets ──
      const now=Date.now(), blink=(now%(2*X_BLINK_MS))<X_BLINK_MS;
      let sc=0, xc=0, hc=0;

      for (let s=0; s<MAX_SIG; s++) {
        const sig=sigs[s];

        if (sig.broken) {
          if (now-sig.brokenAt>X_LIFE_MS) { sig.broken=false; sig.state='dead'; sig.stateAt=now; }
          else {
            const base=xc*12, S=X_SIZE;
            xPosBuf[base+0]=sig.bx-S; xPosBuf[base+1]=sig.by+S; xPosBuf[base+2]=sig.bz;
            xPosBuf[base+3]=sig.bx+S; xPosBuf[base+4]=sig.by-S; xPosBuf[base+5]=sig.bz;
            xPosBuf[base+6]=sig.bx+S; xPosBuf[base+7]=sig.by+S; xPosBuf[base+8]=sig.bz;
            xPosBuf[base+9]=sig.bx-S; xPosBuf[base+10]=sig.by-S; xPosBuf[base+11]=sig.bz;
            xc++;
          }
          continue;
        }

        if (sig.state==='dead') { if (now-sig.stateAt>DEAD_MS) spawnSig(sig); continue; }

        if (sig.state==='arrived') {
          const dest=sig.path[sig.path.length-1];
          sigPosBuf[sc*3]=currPos[dest*3]; sigPosBuf[sc*3+1]=currPos[dest*3+1]; sigPosBuf[sc*3+2]=currPos[dest*3+2];
          sc++;
          if (now-sig.stateAt>ARRIVE_MS) { sig.state='dead'; sig.stateAt=now; }
          continue;
        }

        const from=sig.path[sig.pathIdx], to=sig.path[sig.pathIdx+1];

        if (nodeDisplaced(from)||nodeDisplaced(to)) {
          const t=sig.progress;
          sig.bx=currPos[from*3]*(1-t)+currPos[to*3]*t;
          sig.by=currPos[from*3+1]*(1-t)+currPos[to*3+1]*t;
          sig.bz=currPos[from*3+2]*(1-t)+currPos[to*3+2]*t;
          sig.broken=true; sig.brokenAt=now; continue;
        }

        sig.progress+=SIG_SPEED;
        if (sig.progress>=1.0) {
          sig.pathIdx++; sig.progress=0;
          if (sig.pathIdx>=sig.path.length-1) { sig.state='arrived'; sig.stateAt=now; continue; }
        }

        const t=sig.progress, fi=sig.path[sig.pathIdx], ti=sig.path[sig.pathIdx+1];
        sigPosBuf[sc*3]  =currPos[fi*3]*(1-t)+currPos[ti*3]*t;
        sigPosBuf[sc*3+1]=currPos[fi*3+1]*(1-t)+currPos[ti*3+1]*t;
        sigPosBuf[sc*3+2]=currPos[fi*3+2]*(1-t)+currPos[ti*3+2]*t;
        sc++;

        hlPosBuf[hc*6]  =currPos[fi*3];   hlPosBuf[hc*6+1]=currPos[fi*3+1]; hlPosBuf[hc*6+2]=currPos[fi*3+2];
        hlPosBuf[hc*6+3]=currPos[ti*3];   hlPosBuf[hc*6+4]=currPos[ti*3+1]; hlPosBuf[hc*6+5]=currPos[ti*3+2];
        hc++;
      }

      sigGeom.setDrawRange(0,sc); sigPA.needsUpdate=true;
      hlBufArr.set(hlPosBuf.subarray(0, hc*6));
      if (hc < MAX_SIG) hlBufArr.fill(0, hc*6);
      hlInstBuf.needsUpdate = true;
      xGeom.setDrawRange(0,xc*4); xPA.needsUpdate=true;
      xMat.opacity=blink&&xc>0?0.95:0.0;

      renderer.render(scene, camera);
    }
    animate();

    const onResize=()=>{ camera.aspect=window.innerWidth/window.innerHeight; camera.updateProjectionMatrix(); renderer.setSize(window.innerWidth,window.innerHeight); intraMat.resolution.set(window.innerWidth,window.innerHeight); interMat.resolution.set(window.innerWidth,window.innerHeight); hlMat.resolution.set(window.innerWidth,window.innerHeight); };
    window.addEventListener('resize', onResize);

    return () => {
      window.removeEventListener('mousemove', onMouseMove);
      window.removeEventListener('resize', onResize);
      cancelAnimationFrame(animId);
      intraGeom.dispose(); intraMat.dispose();
      interGeom.dispose(); interMat.dispose();
      hlGeom.dispose();    hlMat.dispose();
      lineMatRef.current=null; gwMatRef.current=null;
      sigMatRef.current=null; xMatRef.current=null; hlMatRef.current=null;
      renderer.dispose();
      if (container.contains(renderer.domElement)) container.removeChild(renderer.domElement);
    };
  }, []);
}
